                ResultSrcD    = 3'b000;
                BranchD       = 1'b0;
                JumpD         = 1'b0;
                ALUResultSrcD = 1'b0;
                ALUSelectD    = funct3;
                SubArithD     = (funct3 == 3'b010) || (funct3 == 3'b011) ||
                                ((funct3 == 3'b101) && (funct7 == 7'b0100000));
                legal_instr   = legal_itype;
            end

            7'b0010111: begin
