                ResultSrcD    = 3'b000;
                BranchD       = 1'b0;
                JumpD         = 1'b0;
                ALUResultSrcD = 1'b0;
                ALUSelectD    = 3'b000;
                SubArithD     = 1'b0;
                legal_instr   = legal_store;
            end

            7'b0110011: begin
                RegWriteD     = 1'b1;
                ImmSrcD       = 3'b000;
                ALUSrcAD      = 1'b0;
                ALUSrcBD      = 1'b0;
                MemRWD        = 2'b00;
                ResultSrcD    = 3'b000;
                BranchD       = 1'b0;
                JumpD         = 1'b0;
                ALUResultSrcD = 1'b0;
                ALUSelectD    = funct3;
                SubArithD     = (funct3 == 3'b010) || (funct3 == 3'b011) ||
                                ((funct3 == 3'b000) && (funct7 == 7'b0100000)) ||
                                ((funct3 == 3'b101) && (funct7 == 7'b0100000));
                legal_instr   = legal_rtype;
            end

            7'b0110111: begin
                RegWriteD     = 1'b1;
                ImmSrcD       = 3'b100;
                ALUSrcAD      = 1'b0;
                ALUSrcBD      = 1'b1;
                MemRWD        = 2'b00;
                ResultSrcD    = 3'b000;
                BranchD       = 1'b0;
                JumpD         = 1'b0;
                ALUResultSrcD = 1'b1;
                ALUSelectD    = 3'b000;
                SubArithD     = 1'b0;
                legal_instr   = 1'b1;
            end

