                RegWriteD     = 1'b0;
                ImmSrcD       = 3'b010;
                ALUSrcAD      = 1'b1;
                ALUSrcBD      = 1'b1;
                MemRWD        = 2'b00;
                ResultSrcD    = 3'b000;
                BranchD       = 1'b1;
                JumpD         = 1'b0;
                ALUResultSrcD = 1'b0;
                ALUSelectD    = 3'b000;
                SubArithD     = 1'b0;
                legal_instr   = legal_branch;
            end

            7'b1100111: begin
                RegWriteD     = 1'b1;
                ImmSrcD       = 3'b000;
                ALUSrcAD      = 1'b0;
                ALUSrcBD      = 1'b1;
                MemRWD        = 2'b00;
                ResultSrcD    = 3'b000;
                BranchD       = 1'b0;
                JumpD         = 1'b1;
                ALUResultSrcD = 1'b1;
                ALUSelectD    = 3'b000;
                SubArithD     = 1'b0;
                legal_instr   = legal_jalr;
            end

            7'b1101111: begin
                RegWriteD     = 1'b1;
                ImmSrcD       = 3'b011;
                ALUSrcAD      = 1'b1;
                ALUSrcBD      = 1'b1;
                MemRWD        = 2'b00;
                ResultSrcD    = 3'b000;
                BranchD       = 1'b0;
                JumpD         = 1'b1;
                ALUResultSrcD = 1'b1;
                ALUSelectD    = 3'b000;
                SubArithD     = 1'b0;
                legal_instr   = 1'b1;
            end

            default: begin
                legal_instr   = 1'b0;
            end
        endcase

        IllegalInstrD = ~legal_instr;

        if (IllegalInstrD) begin
            RegWriteD = 1'b0;
            MemRWD    = 2'b00;
            BranchD   = 1'b0;
            JumpD     = 1'b0;
